var DEFAULT_OUTPUT_FILE = "index.html";
var DEFAULT_HTTP_RPC_BASE_URL = "https://<baseURL>";
function resolveOutFile(input) {
  const outFile = getOptionString(
    input.options,
    "outFile",
    DEFAULT_OUTPUT_FILE
  );
  const trimmedOutFile = outFile.trim();
  const finalOutFile = trimmedOutFile.length > 0 ? trimmedOutFile : DEFAULT_OUTPUT_FILE;
  assert(
    finalOutFile.endsWith(".html"),
    `Invalid outFile "${finalOutFile}". The output file must end with .html`
  );
  return finalOutFile;
}
__name(resolveOutFile, "resolveOutFile");
function resolveHttpRpcBaseUrls(input) {
  const baseUrls = getOptionArray(
    input.options,
    "httpRpcBaseUrl",
    [],
    ","
  );
  return baseUrls.length > 0 ? baseUrls : [DEFAULT_HTTP_RPC_BASE_URL];
}
__name(resolveHttpRpcBaseUrls, "resolveHttpRpcBaseUrls");
var generate = definePlugin((input) => {
  input.ir.entryPoint = "";
  const outFile = resolveOutFile(input);
  const ir = escapeScriptTag(JSON.stringify(anonymizeIr(input.ir)));
  const httpRpcBaseUrl = escapeScriptTag(
    JSON.stringify(resolveHttpRpcBaseUrls(input).join(","))
  );
  let html = build_default.replace(
    "window.__vdl_ir = {};",
    `window.__vdl_ir = ${ir};`
  );
  html = html.replace(
    'window.__vdl_http_rpc_base_url = "https://<baseURL>";',
    `window.__vdl_http_rpc_base_url = ${httpRpcBaseUrl};`
  );
  return {
    files: [
      {
        path: outFile,
        content: html
      }
    ]
  };
});
